-- Crushly setup part 46 of 47 (from 20261101140000_mention_and_tag_suggest.sql) — generated by npm run bundle:sql.
-- Run the parts in order in the Supabase SQL editor. Re-running is safe.
-- Who and what you mean when you type @ and #.
--
-- Both are the same question — finish this word for me — asked about two
-- different kinds of thing: a person, and a tag somebody already used. The
-- client decides which is being typed (see `lib/mentions.ts`) and these two
-- functions answer it.
--
-- Neither returns anything the asker could not already see: mentions obey the
-- same visibility rules as search, and tags are counted only from Flows the
-- asker can open.

/**
 * People whose handle or name starts with what has been typed.
 *
 * A prefix, not a fuzzy contains: `@ad` should offer Ada before it offers
 * somebody whose middle name happens to be Adebayo. People you are connected to
 * come first, because a mention is usually aimed at somebody you know.
 */
create or replace function public.mention_suggest(p_query text, p_limit int default 8)
returns jsonb
language plpgsql
stable security definer
set search_path to 'public'
as $function$
declare
  me bigint := public.me_id();
  q text := lower(btrim(coalesce(p_query, '')));
  n int := least(greatest(coalesce(p_limit, 8), 1), 20);
begin
  if me is null then
    perform public.crushly_fail(401, 'unauthorized', 'Please sign in again.');
  end if;
  if char_length(q) < 1 then
    -- Nothing typed yet: the people this member talks to most are the best
    -- guess at who they were about to name.
    return coalesce((
      select jsonb_agg(x.item)
        from (
          select jsonb_build_object(
                   'id', p.id,
                   'name', p.name,
                   'username', p.username,
                   'photo', (select ph.url from photos ph where ph.user_id = p.id order by ph.position limit 1),
                   'connected', public.is_connected_pair(me, p.id)
                 ) as item
            from profiles p
           where p.id <> me and p.onboarded and p.status = 'active'
             and not public.is_blocked_pair(me, p.id)
             and public.is_connected_pair(me, p.id)
           order by p.last_active_at desc nulls last
           limit n
        ) x
    ), '[]'::jsonb);
  end if;

  return coalesce((
    select jsonb_agg(x.item)
      from (
        select jsonb_build_object(
                 'id', p.id,
                 'name', p.name,
                 'username', p.username,
                 'photo', (select ph.url from photos ph where ph.user_id = p.id order by ph.position limit 1),
                 'connected', public.is_connected_pair(me, p.id)
               ) as item
          from profiles p
          left join privacy pr on pr.user_id = p.id
         where p.id <> me
           and p.onboarded
           and p.status = 'active'
           and not public.is_blocked_pair(me, p.id)
           and (lower(coalesce(p.username, '')) like q || '%' or lower(coalesce(p.name, '')) like q || '%')
           and (
             public.is_connected_pair(me, p.id)
             or (coalesce(pr.discoverable, true) and coalesce(pr.incognito, false) = false
                 and coalesce(pr.profile_visibility, 'everyone') = 'everyone')
           )
         order by
           public.is_connected_pair(me, p.id) desc,
           (lower(coalesce(p.username, '')) like q || '%') desc,
           p.name
         limit n
      ) x
  ), '[]'::jsonb);
end $function$;

/**
 * Tags already in use, counted over the Flows the asker may open.
 *
 * Read from the words people actually wrote rather than from a table of
 * approved tags: the tag list is whatever the members have made, and a tag with
 * nobody in it is not worth suggesting.
 */
create or replace function public.tag_suggest(p_query text, p_limit int default 8)
returns jsonb
language plpgsql
stable security definer
set search_path to 'public'
as $function$
declare
  me bigint := public.me_id();
  q text := lower(btrim(coalesce(p_query, '')));
  n int := least(greatest(coalesce(p_limit, 8), 1), 20);
begin
  if me is null then
    perform public.crushly_fail(401, 'unauthorized', 'Please sign in again.');
  end if;

  return coalesce((
    select jsonb_agg(jsonb_build_object('tag', t.tag, 'uses', t.uses) order by t.uses desc, t.tag)
      from (
        select lower(m[1]) as tag, count(*) as uses
          from posts po
          cross join lateral regexp_matches(coalesce(po.body, ''), '#([A-Za-z0-9_]{2,30})', 'g') as m
         where po.circle_id is null
           and public.can_view_post(po, me)
           and (q = '' or lower(m[1]) like q || '%')
         group by lower(m[1])
         order by count(*) desc
         limit n
      ) t
  ), '[]'::jsonb);
end $function$;
